function fmtCurrency(value?: number | null) {
  if (value === null || value === undefined) return '—';
  return new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(value);
}
function fmtDate(value?: string | null) {
  if (!value) return '—';
  return new Intl.DateTimeFormat('en-IN', { day: '2-digit', month: 'short', year: 'numeric' }).format(new Date(value));
}
function levelTone(level?: string) {
  if (level === 'Elevated') return 'tone-elevated';
  if (level === 'Moderate') return 'tone-moderate';
  if (level === 'Low') return 'tone-low';
  return 'tone-neutral';
}
function StatusPill({ level, children }: { level?: string; children?: ReactNode }) {
  return <span className={`status-pill ${levelTone(level)}`} data-testid={`status-${level ?? 'neutral'}`}><span className="status-dot" />{children ?? level}</span>;
}
function Skeleton({ className = '' }: { className?: string }) {
  return <div className={`animate-pulse rounded-lg bg-muted/70 ${className}`} />;
}
function LoadingPanel() {
  return <div className="space-y-4"><Skeleton className="h-7 w-1/3" /><Skeleton className="h-32 w-full" /><Skeleton className="h-24 w-full" /></div>;
}
function QueryState({ loading, error, onRetry, children }: { loading?: boolean; error?: unknown; onRetry?: () => void; children: ReactNode }) {
  if (loading) return <LoadingPanel />;
  if (error) return <div className="panel p-8 text-center"><AlertTriangle className="mx-auto mb-3 h-8 w-8 text-destructive" /><h3 className="font-semibold">Could not load this view</h3><p className="mt-1 text-sm text-muted-foreground">The service did not return a usable response.</p><button data-testid="button-retry" onClick={onRetry} className="button-secondary mt-4"><RefreshCw className="h-4 w-4" /> Try again</button></div>;
  return <>{children}</>;
}
function PageHeader({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: ReactNode }) {
  return <div className="mb-8 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><div className="eyebrow text-primary">{eyebrow}</div><h1 className="display-serif mt-2 text-4xl leading-none tracking-tight text-foreground md:text-5xl">{title}</h1>{description && <p className="mt-3 max-w-2xl text-sm leading-6 text-muted-foreground">{description}</p>}</div>{action}</div>;
}
function Metric({ label, value, detail, icon: Icon, accent = false }: { label: string; value: ReactNode; detail?: string; icon: typeof Gauge; accent?: boolean }) {
  return <div className={`panel p-5 ${accent ? 'metric-accent' : ''}`} data-testid={`metric-${label.toLowerCase().replaceAll(' ', '-')}`}><div className="flex items-start justify-between"><span className="eyebrow text-muted-foreground">{label}</span><Icon className={`h-4 w-4 ${accent ? 'text-accent' : 'text-primary'}`} /></div><div className="data-mono mt-5 text-3xl font-bold tracking-tight">{value}</div>{detail && <div className="mt-2 text-xs text-muted-foreground">{detail}</div>}</div>;
}
function MiniBars({ points, color = 'hsl(var(--primary))' }: { points?: { label: string; value: number }[]; color?: string }) {
  const data = points?.length ? points : [{ label: '—', value: 1 }];
  const max = Math.max(...data.map((point) => point.value), 1);
  return <div className="flex h-36 items-end gap-2">{data.map((point, index) => <div className="group flex min-w-0 flex-1 flex-col items-center gap-2" key={`${point.label}-${index}`}><div className="relative flex h-28 w-full items-end"><div title={`${point.label}: ${point.value}`} className="w-full rounded-t-md transition-all duration-300 group-hover:opacity-75" style={{ height: `${Math.max(6, point.value / max * 100)}%`, background: color }} /></div><span className="data-mono max-w-full truncate text-[9px] text-muted-foreground">{point.label}</span></div>)}</div>;
}
function SparkLine({ points }: { points?: { label: string; value: number }[] }) {
  const data = points?.length ? points : [{ label: '', value: 1 }, { label: '', value: 2 }];
  const max = Math.max(...data.map((d) => d.value), 1); const min = Math.min(...data.map((d) => d.value), 0);
  const pointsString = data.map((d, i) => `${i / Math.max(data.length - 1, 1) * 100},${100 - ((d.value - min) / Math.max(max - min, 1) * 80 + 10)}`).join(' ');
  return <svg viewBox="0 0 100 100" preserveAspectRatio="none" className="h-20 w-full"><polyline fill="none" stroke="hsl(var(--primary))" strokeWidth="2.5" vectorEffect="non-scaling-stroke" points={pointsString} /><polyline fill="hsl(var(--primary) / .08)" stroke="none" points={`0,100 ${pointsString} 100,100`} /></svg>;
}
function Empty({ title, text }: { title: string; text: string }) {
  return <div className="panel flex flex-col items-center justify-center p-12 text-center"><div className="mb-4 rounded-full bg-secondary p-4 text-primary"><Database className="h-6 w-6" /></div><h3 className="font-semibold">{title}</h3><p className="mt-2 max-w-sm text-sm leading-6 text-muted-foreground">{text}</p></div>;
}
function Disclaimer({ network = false }: { network?: boolean }) {
  return <div className="disclaimer mt-6 flex gap-3 p-4 text-xs leading-5 text-muted-foreground"><Info className="mt-0.5 h-4 w-4 shrink-0 text-primary" /><span>{network ? NETWORK_NOTE : DISCLAIMER}</span></div>;
}

function Sidebar({ open, onClose }: { open: boolean; onClose: () => void }) {
  const [location] = useLocation();
  const { data: health } = useHealthCheck();
  return <><div className={`sidebar-surface fixed inset-y-0 left-0 z-40 flex w-[248px] flex-col border-r border-sidebar-border transition-transform duration-200 md:translate-x-0 ${open ? 'translate-x-0' : '-translate-x-full'}`}><div className="flex h-20 items-center justify-between px-6"><Link href="/dashboard" onClick={onClose} className="flex items-center gap-3" data-testid="link-brand"><div className="brand-mark"><span /></div><div><div className="font-bold tracking-tight text-sidebar-foreground">BidShield</div><div className="eyebrow mt-0.5 text-sidebar-foreground/50">evidence desk</div></div></Link><button onClick={onClose} className="text-sidebar-foreground/60 md:hidden" data-testid="button-close-menu"><X className="h-5 w-5" /></button></div><div className="px-4 pb-4"><div className="rounded-lg border border-sidebar-border bg-sidebar-accent/60 px-3 py-2"><div className="flex items-center gap-2 text-xs text-sidebar-foreground/70"><span className={`status-dot ${health?.status === 'ok' ? 'bg-primary' : 'bg-accent'}`} />Data workspace</div><div className="mt-1 text-[11px] text-sidebar-foreground/45">National procurement corpus</div></div></div><nav className="scroll-thin flex-1 overflow-y-auto px-3"><div className="eyebrow mb-2 px-3 text-sidebar-foreground/40">Review</div>{nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={onClose} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`} className={`nav-link ${location.startsWith(href) ? 'nav-link-active' : ''}`}><Icon className="h-[17px] w-[17px]" />{label}</Link>)}<div className="eyebrow mb-2 mt-8 px-3 text-sidebar-foreground/40">Data room</div>{dataNav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={onClose} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`} className={`nav-link ${location.startsWith(href) ? 'nav-link-active' : ''}`}><Icon className="h-[17px] w-[17px]" />{label}</Link>)}</nav><div className="border-t border-sidebar-border p-4"><Link href="/settings" onClick={onClose} data-testid="link-nav-settings" className="nav-link"><Settings className="h-[17px] w-[17px]" />Settings</Link><div className="mt-3 flex items-center gap-2 px-3 text-[11px] text-sidebar-foreground/45"><span className="status-dot bg-primary" />Screening workspace ready</div></div></div>{open && <button aria-label="Close navigation" onClick={onClose} className="fixed inset-0 z-30 bg-black/20 md:hidden" data-testid="button-sidebar-overlay" />}</>;
}
function Shell({ children }: { children: ReactNode }) {
  const [menuOpen, setMenuOpen] = useState(false);
  return <div className="app-shell"><Sidebar open={menuOpen} onClose={() => setMenuOpen(false)} /><div className="md:pl-[248px]"><header className="sticky top-0 z-20 flex h-16 items-center justify-between border-b hairline bg-background/90 px-5 backdrop-blur md:px-10"><div className="flex items-center gap-3"><button onClick={() => setMenuOpen(true)} className="rounded-md p-2 hover:bg-secondary md:hidden" data-testid="button-open-menu"><Menu className="h-5 w-5" /></button><div className="hidden text-xs text-muted-foreground md:block">Public procurement / <span className="text-foreground">Evidence review</span></div></div><div className="flex items-center gap-3"><button className="relative rounded-md p-2 text-muted-foreground hover:bg-secondary" data-testid="button-notifications"><Bell className="h-4 w-4" /><span className="absolute right-1 top-1 h-1.5 w-1.5 rounded-full bg-accent" /></button><div className="flex h-8 w-8 items-center justify-center rounded-full bg-primary text-xs font-bold text-primary-foreground" data-testid="avatar-user">AR</div><span className="hidden text-xs font-medium sm:inline">Analyst room</span></div></header><main className="mx-auto max-w-[1440px] px-5 py-8 md:px-10">{children}</main></div></div>;
}

function Dashboard() {
  const query = useGetDashboardSummary();
  const data = query.data;
  return <PageFrame><PageHeader eyebrow="Command center / 06 Feb 2025" title="See the signals. Keep the judgment." description="A focused view of procurement activity, screening indicators, and the investigations that need a human eye today." action={<Link href="/data" className="button-primary" data-testid="link-upload-data"><Upload className="h-4 w-4" /> Add procurement data</Link>} /><QueryState loading={query.isLoading} error={query.error} onRetry={() => query.refetch()}>{data && <><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Tenders reviewed" value={data.totalTenders.toLocaleString()} detail="Across all active datasets" icon={FileCheck2} /><Metric label="Companies observed" value={data.totalCompanies.toLocaleString()} detail="Canonical entities resolved" icon={Building2} /><Metric label="Bids recorded" value={data.totalBids.toLocaleString()} detail="Participation events" icon={BarChart3} /><Metric label="Review queue" value={data.reviewCount.toLocaleString()} detail="Indicators requiring review" icon={AlertTriangle} accent /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.6fr_1fr]"><div className="panel p-6"><div className="flex items-start justify-between"><div><div className="eyebrow text-muted-foreground">Volume over time</div><h2 className="mt-2 text-lg font-semibold">Tender activity</h2></div><span className="rounded-md bg-secondary px-2.5 py-1 text-xs text-muted-foreground">Monthly</span></div><div className="mt-5"><MiniBars points={data.tenderVolume} /></div></div><div className="panel p-6"><div className="eyebrow text-muted-foreground">Screening distribution</div><h2 className="mt-2 text-lg font-semibold">Where to look next</h2><div className="mt-5 space-y-4">{data.screeningDistribution.map((item) => <div key={item.label} data-testid={`row-screening-${item.label}`}><div className="mb-1.5 flex justify-between text-xs"><span>{item.label}</span><span className="data-mono text-muted-foreground">{item.value}</span></div><div className="h-2 rounded-full bg-secondary"><div className="h-2 rounded-full bg-primary transition-all" style={{ width: `${Math.min(item.value / Math.max(...data.screeningDistribution.map((d) => d.value), 1) * 100, 100)}%` }} /></div></div>)}</div><Disclaimer /></div></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.15fr_.85fr]"><div className="panel p-6"><div className="flex items-start justify-between"><div><div className="eyebrow text-muted-foreground">Market shape</div><h2 className="mt-2 text-lg font-semibold">Value by category</h2></div><BarChart3 className="h-5 w-5 text-primary" /></div><div className="mt-4"><MiniBars points={data.categoryValues} color="hsl(var(--chart-2))" /></div></div><div className="panel p-6"><div className="eyebrow text-muted-foreground">Geographic footprint</div><h2 className="mt-2 text-lg font-semibold">Tenders by state</h2><div className="mt-5 space-y-3">{data.stateCounts.slice(0, 6).map((item, i) => <div className="flex items-center gap-3" key={item.label}><span className="data-mono w-5 text-xs text-muted-foreground">{String(i + 1).padStart(2, '0')}</span><span className="flex-1 text-sm">{item.label}</span><span className="data-mono text-sm font-bold">{item.value}</span><div className="h-1.5 w-20 rounded-full bg-secondary"><div className="h-full rounded-full bg-chart-3" style={{ width: `${Math.min(item.value / Math.max(...data.stateCounts.map((d) => d.value), 1) * 100, 100)}%` }} /></div></div>)}</div></div></div><div className="panel mt-6 overflow-hidden"><div className="flex items-center justify-between border-b hairline px-6 py-5"><div><div className="eyebrow text-muted-foreground">Active workspaces</div><h2 className="mt-2 text-lg font-semibold">Recent investigations</h2></div><Link href="/investigations" className="text-xs font-semibold text-primary hover:underline" data-testid="link-all-investigations">View all <ArrowRight className="ml-1 inline h-3 w-3" /></Link></div><InvestigationRows items={data.recentInvestigations} /></div></>}</QueryState></PageFrame>;
}
function PageFrame({ children }: { children: ReactNode }) { return <>{children}</>; }
function InvestigationRows({ items }: { items?: any[] }) {
  if (!items?.length) return <div className="p-8"><Empty title="No investigations yet" text="When screening indicators are ready for review, they will appear here." /></div>;
  return <div className="divide-y divide-border">{items.map((item) => <Link href={`/investigations/${item.id}`} key={item.id} className="grid grid-cols-[1fr_auto] items-center gap-4 px-6 py-4 transition-colors hover:bg-secondary/45 md:grid-cols-[1.2fr_1fr_auto_auto]"><div><div className="font-medium">{item.title}</div><div className="data-mono mt-1 text-[11px] text-muted-foreground">{item.tenderNumber}</div></div><div className="hidden text-sm text-muted-foreground md:block">{item.indicatorCount} indicators</div><StatusPill level={item.screeningLevel} /><span className="hidden text-xs text-muted-foreground md:block">{item.status}</span></Link>)}</div>;
}

function Tenders() {
  const [search, setSearch] = useState(''); const [screening, setScreening] = useState('All'); const [page, setPage] = useState(1);
  const params = useMemo(() => ({ search: search || undefined, screening: screening as any, page, pageSize: 10 }), [search, screening, page]);
  const query = useGetTenders(params); const data = query.data;
  return <PageFrame><PageHeader eyebrow="Review / tender directory" title="Tenders" description="Search the procurement record, then open a tender to inspect bidders, indicators, and supporting evidence." action={<div className="eyebrow text-muted-foreground">{data?.total ?? '—'} records</div>} /><div className="panel mb-5 p-4"><div className="flex flex-col gap-3 lg:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><input value={search} onChange={(e) => { setSearch(e.target.value); setPage(1); }} placeholder="Search title, tender number, organization…" className="input pl-10" data-testid="input-search-tenders" /></div><div className="flex items-center gap-2"><ListFilter className="h-4 w-4 text-muted-foreground" /><select value={screening} onChange={(e) => { setScreening(e.target.value); setPage(1); }} className="input w-full lg:w-44" data-testid="select-screening-tenders"><option>All</option><option>Low</option><option>Moderate</option><option>Elevated</option></select></div></div></div><QueryState loading={query.isLoading} error={query.error} onRetry={() => query.refetch()}>{data?.items.length ? <div className="panel overflow-hidden"><div className="table-scroll"><table className="data-table"><thead><tr><th>Tender</th><th>Organization</th><th>Value</th><th>Bidders</th><th>Screening</th><th>Closing</th><th /></tr></thead><tbody>{data.items.map((tender) => <tr key={tender.id} data-testid={`row-tender-${tender.id}`}><td><Link href={`/tenders/${tender.id}`} className="font-semibold text-foreground hover:text-primary">{tender.tenderNumber}</Link><div className="mt-1 max-w-xs truncate text-xs text-muted-foreground">{tender.title}</div></td><td><div className="text-sm">{tender.organization}</div><div className="mt-1 text-xs text-muted-foreground">{tender.state} · {tender.category}</div></td><td className="data-mono text-sm">{fmtCurrency(tender.estimatedValue)}</td><td className="data-mono text-sm">{tender.bidderCount}</td><td><StatusPill level={tender.screeningLevel} /></td><td className="text-xs text-muted-foreground">{fmtDate(tender.closingDate)}</td><td><Link href={`/tenders/${tender.id}`} className="icon-button" data-testid={`link-tender-${tender.id}`}><ArrowRight className="h-4 w-4" /></Link></td></tr>)}</tbody></table></div><div className="flex items-center justify-between border-t hairline px-5 py-4 text-xs text-muted-foreground"><span>Page {data.page} of {Math.max(1, Math.ceil(data.total / data.pageSize))}</span><div className="flex gap-2"><button disabled={page <= 1} onClick={() => setPage(page - 1)} className="button-quiet" data-testid="button-tenders-previous"><ArrowLeft className="h-3.5 w-3.5" /> Previous</button><button disabled={page >= Math.ceil(data.total / data.pageSize)} onClick={() => setPage(page + 1)} className="button-quiet" data-testid="button-tenders-next">Next <ArrowRight className="h-3.5 w-3.5" /></button></div></div></div> : <Empty title="No tenders match those filters" text="Try a broader search or clear the screening filter." />}</QueryState></PageFrame>;
}

function TenderDetailPage() {
  const { id } = useParams<{ id: string }>(); const query = useGetTender(Number(id)); const tender = query.data;
  return <PageFrame><BackLink href="/tenders" label="Tender directory" /><QueryState loading={query.isLoading} error={query.error} onRetry={() => query.refetch()}>{tender && <><PageHeader eyebrow={`${tender.tenderNumber} / tender record`} title={tender.title} description={`${tender.organization} · ${tender.department} · ${tender.location}`} action={<StatusPill level={tender.screeningLevel} />} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Estimated value" value={fmtCurrency(tender.estimatedValue)} detail={`Awarded ${fmtCurrency(tender.contractValue)}`} icon={Gauge} /><Metric label="Bidders" value={tender.bidderCount} detail="Recorded submissions" icon={Users} /><Metric label="Indicators" value={tender.indicatorCount} detail="Signals for review" icon={AlertTriangle} accent /><Metric label="Closing date" value={fmtDate(tender.closingDate)} detail={`Published ${fmtDate(tender.tenderDate)}`} icon={FileCheck2} /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.3fr_.7fr]"><div className="space-y-6"><section className="panel overflow-hidden"><div className="border-b hairline px-6 py-5"><div className="eyebrow text-muted-foreground">Participation</div><h2 className="mt-2 text-lg font-semibold">Bidders and submitted values</h2></div><div className="table-scroll"><table className="data-table"><thead><tr><th>Company</th><th>Bid amount</th><th>Distance from winner</th><th>Rank</th></tr></thead><tbody>{tender.bids.map((bid) => <tr key={bid.companyId}><td><Link href={`/companies/${bid.companyId}`} className="font-semibold hover:text-primary">{bid.companyName}</Link>{bid.isWinner && <span className="ml-2 rounded bg-primary/10 px-1.5 py-0.5 text-[10px] font-bold text-primary">WINNER</span>}</td><td className="data-mono">{fmtCurrency(bid.bidAmount)}</td><td className="data-mono text-muted-foreground">{bid.differenceFromWinner.toFixed(1)}%</td><td className="data-mono">{bid.rank}</td></tr>)}</tbody></table></div></section><section className="panel p-6"><div className="eyebrow text-muted-foreground">Evidence register</div><h2 className="mt-2 text-lg font-semibold">What the indicators are measuring</h2><div className="mt-5 space-y-3">{tender.evidence.length ? tender.evidence.map((evidence) => <div key={evidence.id} className="rounded-lg border hairline bg-background/50 p-4"><div className="flex items-start justify-between gap-3"><div><div className="font-semibold">{evidence.indicatorType}</div><p className="mt-1 text-sm leading-6 text-muted-foreground">{evidence.description}</p></div><span className="data-mono rounded bg-secondary px-2 py-1 text-xs">{evidence.confidence.toFixed(0)}% confidence</span></div><div className="mt-3 flex flex-wrap gap-4 text-xs text-muted-foreground"><span>Metric: <b className="text-foreground">{evidence.metric}</b></span><span>Observed: <b className="text-foreground">{evidence.observedValue ?? '—'}</b></span><span>Expected: <b className="text-foreground">{evidence.expectedValue ?? '—'}</b></span></div></div>) : <Empty title="No evidence recorded" text="This tender has not completed screening analysis." />}</div></section></div><aside className="space-y-6"><section className="panel p-6"><div className="eyebrow text-muted-foreground">Screening summary</div><h2 className="mt-2 text-lg font-semibold">Indicator profile</h2><div className="mt-5 space-y-4">{[['Rotation', tender.screening.rotation], ['Cover bid', tender.screening.coverBid], ['Price clustering', tender.screening.priceClustering], ['Network', tender.screening.network], ['Neat loss', tender.screening.neatLoss]].map(([label, value]) => <div key={String(label)}><div className="mb-1.5 flex justify-between text-sm"><span>{label}</span><span className="data-mono">{value === null ? '—' : `${value}%`}</span></div><div className="h-1.5 rounded-full bg-secondary"><div className="h-full rounded-full bg-primary" style={{ width: `${Number(value ?? 0)}%` }} /></div></div>)}</div><Disclaimer /></section><section className="panel p-6"><div className="eyebrow text-muted-foreground">Award context</div><h2 className="mt-2 text-lg font-semibold">{tender.winner ?? 'Winner not recorded'}</h2><div className="mt-4 grid grid-cols-2 gap-3 text-sm"><div className="rounded-lg bg-secondary/70 p-3"><div className="text-xs text-muted-foreground">Department</div><div className="mt-1 font-medium">{tender.department}</div></div><div className="rounded-lg bg-secondary/70 p-3"><div className="text-xs text-muted-foreground">Category</div><div className="mt-1 font-medium">{tender.category}</div></div></div></section></aside></div></>}</QueryState></PageFrame>;
}
function BackLink({ href, label }: { href: string; label: string }) { return <Link href={href} className="mb-7 inline-flex items-center gap-2 text-xs font-semibold text-muted-foreground hover:text-primary" data-testid="link-back"><ArrowLeft className="h-3.5 w-3.5" /> {label}</Link>; }

function Companies() {
  const [search, setSearch] = useState(''); const [screening, setScreening] = useState('All'); const query = useGetCompanies({ search: search || undefined, screening: screening as any, page: 1, pageSize: 50 }); const data = query.data;
  return <PageFrame><PageHeader eyebrow="Review / entity directory" title="Companies" description="Understand participation context without collapsing a statistical signal into a conclusion." /><div className="panel mb-5 p-4"><div className="flex flex-col gap-3 md:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search canonical or normalized name…" className="input pl-10" data-testid="input-search-companies" /></div><select value={screening} onChange={(e) => setScreening(e.target.value)} className="input md:w-44" data-testid="select-screening-companies"><option>All</option><option>Low</option><option>Moderate</option><option>Elevated</option></select></div></div><QueryState loading={query.isLoading} error={query.error} onRetry={() => query.refetch()}>{data?.items.length ? <div className="panel overflow-hidden"><div className="table-scroll"><table className="data-table"><thead><tr><th>Company</th><th>Participation</th><th>Wins</th><th>Win rate</th><th>Co-participants</th><th>Context</th><th /></tr></thead><tbody>{data.items.map((company) => <tr key={company.id}><td><Link href={`/companies/${company.id}`} className="font-semibold hover:text-primary">{company.canonicalName}</Link><div className="mt-1 text-xs text-muted-foreground">{company.address ?? company.normalizedName}</div></td><td className="data-mono">{company.tendersParticipated}</td><td className="data-mono">{company.wins}</td><td className="data-mono">{company.winRate.toFixed(1)}%</td><td className="data-mono">{company.coParticipants}</td><td><StatusPill level={company.screeningLevel} /></td><td><Link href={`/companies/${company.id}`} className="icon-button" data-testid={`link-company-${company.id}`}><ArrowRight className="h-4 w-4" /></Link></td></tr>)}</tbody></table></div></div> : <Empty title="No companies in this view" text="Broaden the search or import a dataset to populate the company directory." />}</QueryState></PageFrame>;
}

function CompanyDetailPage() {
  const { id } = useParams<{ id: string }>(); const query = useGetCompany(Number(id)); const company = query.data;
  return <PageFrame><BackLink href="/companies" label="Company directory" /><QueryState loading={query.isLoading} error={query.error} onRetry={() => query.refetch()}>{company && <><PageHeader eyebrow="Entity profile / canonical record" title={company.canonicalName} description={`${company.address ?? 'Address not supplied'}${company.state ? ` · ${company.state}` : ''}`} action={<StatusPill level={company.screeningLevel} />} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Tenders participated" value={company.tendersParticipated} detail="Observed participation" icon={FileCheck2} /><Metric label="Wins" value={company.wins} detail={`${company.winRate.toFixed(1)}% win rate`} icon={CheckCircle2} /><Metric label="Total bid value" value={fmtCurrency(company.totalBidValue)} detail={`${company.losses} non-winning bids`} icon={Gauge} /><Metric label="Co-participants" value={company.coParticipants} detail="Distinct observed links" icon={Network} accent /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.2fr_.8fr]"><section className="panel p-6"><div className="eyebrow text-muted-foreground">Participation history</div><h2 className="mt-2 text-lg font-semibold">Activity over time</h2><div className="mt-7 h-32"><SparkLine points={company.participationOverTime} /></div><div className="mt-4 flex justify-between text-[10px] text-muted-foreground">{company.participationOverTime.slice(0, 7).map((point) => <span key={point.label}>{point.label}</span>)}</div><div className="mt-8 grid grid-cols-2 gap-4"><div className="rounded-lg bg-secondary/60 p-4"><div className="eyebrow text-muted-foreground">Participation events</div><div className="data-mono mt-2 text-2xl font-bold">{company.participationOverTime.reduce((a, b) => a + b.value, 0)}</div></div><div className="rounded-lg bg-secondary/60 p-4"><div className="eyebrow text-muted-foreground">Recorded wins</div><div className="data-mono mt-2 text-2xl font-bold">{company.winsOverTime.reduce((a, b) => a + b.value, 0)}</div></div></div></section><section className="panel p-6"><div className="eyebrow text-muted-foreground">Identity context</div><h2 className="mt-2 text-lg font-semibold">Known aliases</h2><div className="mt-4 space-y-2">{company.aliases.length ? company.aliases.map((alias) => <div className="flex items-center gap-2 rounded-md bg-secondary/55 px-3 py-2 text-sm" key={alias}><GitBranch className="h-3.5 w-3.5 text-primary" />{alias}</div>) : <p className="text-sm text-muted-foreground">No alternate names recorded.</p>}</div><div className="mt-6 border-t hairline pt-5 text-xs text-muted-foreground"><div>Registration number <span className="float-right data-mono text-foreground">{company.registrationNumber ?? 'Not supplied'}</span></div><div className="mt-3">GSTIN <span className="float-right data-mono text-foreground">{company.gstin ?? 'Not supplied'}</span></div></div></section></div><section className="panel mt-6 overflow-hidden"><div className="border-b hairline px-6 py-5"><div className="eyebrow text-muted-foreground">Observed relationships</div><h2 className="mt-2 text-lg font-semibold">Frequent co-participants</h2></div>{company.frequentCoParticipants.length ? <div className="grid gap-px bg-border sm:grid-cols-2 lg:grid-cols-3">{company.frequentCoParticipants.map((peer) => <Link href={`/companies/${peer.id}`} key={peer.id} className="bg-card p-5 transition-colors hover:bg-secondary/40"><div className="flex items-center justify-between"><div><div className="font-semibold">{peer.canonicalName}</div><div className="mt-1 text-xs text-muted-foreground">{peer.tendersParticipated} shared participation context</div></div><ArrowUpRight className="h-4 w-4 text-primary" /></div><div className="mt-4"><StatusPill level={peer.screeningLevel} /></div></Link>)}</div> : <div className="p-6 text-sm text-muted-foreground">No frequent co-participants are available.</div>}<Disclaimer network /></section></>}</QueryState></PageFrame>;
}

function Investigations() {
  const query = useGetInvestigations(); const [status, setStatus] = useState('All'); const items = query.data?.filter((item) => status === 'All' || item.status === status);
  return <PageFrame><PageHeader eyebrow="Review / casework" title="Investigations" description="A working list for careful review of screening indicators across related tenders." action={<div className="flex gap-2"><button className="button-secondary" data-testid="button-filter-investigations"><Filter className="h-4 w-4" /> Filter</button></div>} /><div className="mb-5 flex gap-2 overflow-auto"><button onClick={() => setStatus('All')} className={`filter-chip ${status === 'All' ? 'filter-chip-active' : ''}`} data-testid="button-status-all">All</button>{['New', 'Under Review', 'Reviewed'].map((item) => <button key={item} onClick={() => setStatus(item)} className={`filter-chip ${status === item ? 'filter-chip-active' : ''}`} data-testid={`button-status-${item.toLowerCase().replaceAll(' ', '-')}`}>{item}</button>)}</div><QueryState loading={query.isLoading} error={query.error} onRetry={() => query.refetch()}>{items?.length ? <div className="grid gap-4 lg:grid-cols-2">{items.map((item) => <Link href={`/investigations/${item.id}`} className="panel panel-hover block p-6" key={item.id} data-testid={`card-investigation-${item.id}`}><div className="flex items-start justify-between gap-3"><div><div className="data-mono text-xs text-primary">{item.tenderNumber}</div><h2 className="mt-2 text-lg font-semibold">{item.title}</h2></div><StatusPill level={item.screeningLevel} /></div><div className="mt-6 flex items-center justify-between border-t hairline pt-4 text-xs text-muted-foreground"><span>{item.indicatorCount} indicators · {item.status}</span><span>{fmtDate(item.lastAnalyzed)}</span></div></Link>)}</div> : <Empty title="No workspaces in this view" text="New screening workspaces will appear here when tenders need review." />}</QueryState><Disclaimer /></PageFrame>;
}
function InvestigationDetailPage() {
  const { id } = useParams<{ id: string }>(); const query = useGetInvestigation(Number(id)); const item = query.data;
  return <PageFrame><BackLink href="/investigations" label="Investigation workspaces" /><QueryState loading={query.isLoading} error={query.error} onRetry={() => query.refetch()}>{item && <><PageHeader eyebrow="Investigation workspace" title={item.title} description={`${item.tenderNumber} · ${item.status}`} action={<StatusPill level={item.screeningLevel} />} /><div className="grid gap-6 xl:grid-cols-[1.3fr_.7fr]"><div className="space-y-6"><section className="panel p-6"><div className="flex items-center justify-between"><div><div className="eyebrow text-muted-foreground">Review brief</div><h2 className="mt-2 text-lg font-semibold">A structured place for judgment</h2></div><ShieldCheck className="h-6 w-6 text-primary" /></div><p className="mt-5 text-sm leading-7 text-muted-foreground">{item.notes ?? 'No analyst notes have been added. Review the linked tender record and evidence register, then record your reasoning in the case file.'}</p><div className="mt-6 flex flex-wrap gap-3"><Link href={`/tenders/${item.tender.id}`} className="button-primary" data-testid="link-investigation-tender">Open tender record <ArrowRight className="h-4 w-4" /></Link><button className="button-secondary" data-testid="button-add-note"><Plus className="h-4 w-4" /> Add note</button></div></section><section className="panel overflow-hidden"><div className="border-b hairline px-6 py-5"><div className="eyebrow text-muted-foreground">Relationship context</div><h2 className="mt-2 text-lg font-semibold">Connected participation records</h2></div>{item.relationships.length ? <div className="divide-y divide-border">{item.relationships.map((edge, index) => <div className="flex items-center justify-between px-6 py-4" key={`${edge.source}-${edge.target}-${index}`}><div className="flex items-center gap-3"><div className="flex h-8 w-8 items-center justify-center rounded-full bg-secondary text-xs font-bold">{String(edge.source).slice(-2)}</div><GitBranch className="h-4 w-4 text-muted-foreground" /><div className="flex h-8 w-8 items-center justify-center rounded-full bg-secondary text-xs font-bold">{String(edge.target).slice(-2)}</div></div><span className="data-mono text-xs text-muted-foreground">{edge.sharedTenderCount} shared tenders</span></div>)}</div> : <div className="p-6 text-sm text-muted-foreground">No relationship records are attached to this workspace.</div>}</section></div><aside><section className="panel p-6"><div className="eyebrow text-muted-foreground">Review guardrails</div><h2 className="mt-2 text-lg font-semibold">Interpret with care</h2><div className="mt-5 space-y-3">{['Read the evidence, not just the level.', 'Compare the observed metric with its expected baseline.', 'Document alternative explanations.', 'Keep the conclusion separate from the indicator.'].map((text, i) => <div className="flex gap-3 text-sm leading-6" key={text}><span className="data-mono text-primary">0{i + 1}</span><span>{text}</span></div>)}</div><Disclaimer /></section></aside></div></>}</QueryState></PageFrame>;
}

function NetworkPage() {
  const query = useGetNetwork(); const data = query.data;
  return <PageFrame><PageHeader eyebrow="Observed structure / network" title="Participation network" description="Explore which companies appear together in the observed procurement record. This is a lens for review, not a finding." action={<button className="button-secondary" onClick={() => query.refetch()} data-testid="button-refresh-network"><RefreshCw className="h-4 w-4" /> Refresh view</button>} /><QueryState loading={query.isLoading} error={query.error} onRetry={() => query.refetch()}>{data && <div className="grid gap-6 xl:grid-cols-[1fr_310px]"><section className="panel min-h-[590px] overflow-hidden p-0"><div className="flex items-center justify-between border-b hairline px-6 py-5"><div><div className="eyebrow text-muted-foreground">Bidder co-occurrence</div><h2 className="mt-2 text-lg font-semibold">{data.nodes.length} companies · {data.edges.length} links</h2></div><div className="flex gap-2 text-[10px] text-muted-foreground"><span className="flex items-center gap-1"><span className="status-dot bg-primary" /> company</span><span className="flex items-center gap-1"><span className="status-dot bg-accent" /> connection</span></div></div><div className="relative h-[490px] overflow-hidden bg-[radial-gradient(circle_at_50%_50%,hsl(var(--primary)/.08),transparent_52%)]"><svg viewBox="0 0 800 500" className="h-full w-full">{data.edges.map((edge, i) => { const s = data.nodes.find((n) => n.id === edge.source); const t = data.nodes.find((n) => n.id === edge.target); return s && t ? <line key={i} x1={s.x} y1={s.y} x2={t.x} y2={t.y} stroke="hsl(var(--accent) / .45)" strokeWidth={Math.max(1, Math.min(edge.sharedTenderCount, 5))} /> : null; })}{data.nodes.map((node) => <g key={node.id} className="cursor-pointer"><circle cx={node.x} cy={node.y} r={Math.max(10, Math.min(node.participationCount / 2, 25))} fill="hsl(var(--primary))" opacity=".9" /><text x={node.x} y={node.y + 4} textAnchor="middle" fontSize="9" fill="hsl(var(--primary-foreground))" fontFamily="var(--app-font-mono)">{String(node.id).slice(-2)}</text><text x={node.x} y={node.y + 38} textAnchor="middle" fontSize="10" fill="hsl(var(--foreground))">{node.label.slice(0, 17)}</text></g>)}</svg></div></section><aside className="space-y-6"><section className="panel p-6"><div className="eyebrow text-muted-foreground">Most connected</div><h2 className="mt-2 text-lg font-semibold">High participation nodes</h2><div className="mt-5 space-y-3">{[...data.nodes].sort((a, b) => b.participationCount - a.participationCount).slice(0, 7).map((node, i) => <div key={node.id} className="flex items-center gap-3"><span className="data-mono w-4 text-[10px] text-muted-foreground">{i + 1}</span><div className="h-7 w-7 rounded-full bg-primary/10 text-center text-[10px] leading-7 text-primary">{String(node.id).slice(-2)}</div><span className="flex-1 truncate text-sm">{node.label}</span><span className="data-mono text-xs">{node.participationCount}</span></div>)}</div></section><Disclaimer network /></aside></div>}</QueryState></PageFrame>;
}

type DataStage = 'upload' | 'validate' | 'clean' | 'resolve' | 'imported';
function DataPage() {
  const [stage, setStage] = useState<DataStage>('upload'); const [file, setFile] = useState<{ filename: string; content: string } | null>(null); const [preview, setPreview] = useState<any>(null); const [validation, setValidation] = useState<any>(null); const [cleaned, setCleaned] = useState<any>(null); const [resolved, setResolved] = useState<any>(null); const [result, setResult] = useState<any>(null); const [message, setMessage] = useState('');
  const upload = useUploadData(); const validate = useValidateData(); const clean = useCleanData(); const resolve = useResolveEntities(); const importData = useImportData();
  const [mapping, setMapping] = useState<Record<string, string | null>>({});
  async function handleFile(input: File) { const content = await input.text(); setFile({ filename: input.name, content }); upload.mutate({ data: { filename: input.name, content } }, { onSuccess: (data) => { setPreview(data); setMapping(data.mapping); setStage('validate'); setMessage('Preview ready. Confirm the column mapping before validation.'); }, onError: () => setMessage('Upload failed. Check the CSV file and try again.') }); }
  function mappedData() { if (!file || !preview) return null; return { filename: file.filename, headers: preview.headers, rows: preview.rows, mapping }; }
  function runValidate() { const data = mappedData(); if (!data) return; validate.mutate({ data }, { onSuccess: (value) => { setValidation(value); setStage('clean'); }, onError: () => setMessage('Validation failed. Try the upload again.') }); }
  function runClean() { const data = mappedData(); if (!data) return; clean.mutate({ data }, { onSuccess: (value) => { setCleaned(value); setStage('resolve'); }, onError: () => setMessage('Cleaning failed. Check the mapping.') }); }
  function runResolve() { resolve.mutate({ data: { rows: (cleaned?.rows ?? preview?.rows ?? []) } }, { onSuccess: (value) => { setResolved(value); setStage('resolve'); }, onError: () => setMessage('Entity resolution could not be completed.') }); }
  function runImport() { if (!file || !preview) return; importData.mutate({ data: { filename: file.filename, rows: cleaned?.rows ?? preview.rows, mapping } }, { onSuccess: (value) => { setResult(value); setStage('imported'); }, onError: () => setMessage('Import failed. No records were changed.') }); }
  const busy = upload.isPending || validate.isPending || clean.isPending || resolve.isPending || importData.isPending;
  return <PageFrame><PageHeader eyebrow="Data room / controlled intake" title="Process procurement data" description="Bring a CSV into the evidence room through a visible, reversible sequence: preview, validate, clean, resolve, then import." /><div className="mb-8 flex flex-wrap items-center gap-2">{[['upload', '01 Upload'], ['validate', '02 Validate'], ['clean', '03 Clean'], ['resolve', '04 Resolve'], ['imported', '05 Import']].map(([key, label], i) => <div key={key} className={`step-chip ${stage === key ? 'step-chip-active' : ''} ${['validate', 'clean', 'resolve', 'imported'].indexOf(stage) >= i ? 'step-chip-done' : ''}`}><span>{i + 1}</span>{label.replace(/^\d+ /, '')}</div>)}</div>{message && <div className="mb-5 flex items-center gap-2 rounded-lg border border-primary/20 bg-primary/5 px-4 py-3 text-sm text-primary"><Info className="h-4 w-4" />{message}</div>}<div className="grid gap-6 xl:grid-cols-[1fr_340px]"><section className="panel p-6">{stage === 'upload' && <div className="flex min-h-[400px] flex-col items-center justify-center rounded-xl border border-dashed border-primary/35 bg-primary/[.025] p-8 text-center"><div className="mb-5 rounded-xl bg-primary/10 p-4 text-primary"><FileSpreadsheet className="h-8 w-8" /></div><h2 className="text-xl font-semibold">Drop a CSV into the evidence room</h2><p className="mt-2 max-w-md text-sm leading-6 text-muted-foreground">The file is previewed before anything is written. Keep source columns intact so every transformation stays traceable.</p><label className="button-primary mt-6 cursor-pointer" data-testid="button-choose-csv"><Upload className="h-4 w-4" /> Choose CSV<input type="file" accept=".csv,text/csv" className="hidden" onChange={(e) => e.target.files?.[0] && handleFile(e.target.files[0])} /></label>{upload.isPending && <p className="mt-4 text-xs text-muted-foreground">Reading and previewing the file…</p>}</div>}{stage !== 'upload' && stage !== 'imported' && preview && <div><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-start"><div><div className="eyebrow text-primary">{preview.filename}</div><h2 className="mt-2 text-xl font-semibold">{preview.rowCount} rows ready for review</h2></div><button className="button-quiet" onClick={() => { setStage('upload'); setPreview(null); setFile(null); }} data-testid="button-replace-file"><X className="h-3.5 w-3.5" /> Replace file</button></div>{stage === 'validate' && <><div className="mt-7"><div className="eyebrow text-muted-foreground">Column mapping</div><p className="mt-2 text-sm text-muted-foreground">Map source fields to procurement concepts. Unmapped fields remain in the source record.</p><div className="mt-4 space-y-2">{preview.headers.map((header: string) => <div key={header} className="flex items-center gap-3 rounded-lg border hairline p-3"><span className="flex-1 truncate text-sm">{header}</span><ArrowRight className="h-4 w-4 text-muted-foreground" /><select value={mapping[header] ?? ''} onChange={(e) => setMapping({ ...mapping, [header]: e.target.value || null })} className="input w-48" data-testid={`select-mapping-${header}`}><option value="">Keep as source field</option><option value="tender_number">Tender number</option><option value="title">Tender title</option><option value="organization">Organization</option><option value="company_name">Company name</option><option value="bid_amount">Bid amount</option><option value="tender_date">Tender date</option><option value="state">State</option></select></div>)}</div></div><button onClick={runValidate} disabled={busy} className="button-primary mt-7" data-testid="button-run-validation">{busy ? 'Validating…' : 'Validate mapping'} <ArrowRight className="h-4 w-4" /></button></>}{stage === 'clean' && validation && <><div className="mt-7 grid grid-cols-2 gap-3 sm:grid-cols-4">{[['Rows', validation.rows], ['Valid', validation.validRows], ['Warnings', validation.warningRows], ['Errors', validation.errorRows]].map(([label, value]) => <div className="rounded-lg bg-secondary/65 p-4" key={String(label)}><div className="eyebrow text-muted-foreground">{label}</div><div className="data-mono mt-2 text-xl font-bold">{value}</div></div>)}</div><div className="mt-5 rounded-lg border hairline p-4"><div className="flex items-center justify-between"><span className="text-sm font-semibold">Quality score</span><span className="data-mono text-lg text-primary">{validation.qualityScore.toFixed(1)}%</span></div><div className="mt-3 h-2 rounded-full bg-secondary"><div className="h-full rounded-full bg-primary" style={{ width: `${validation.qualityScore}%` }} /></div></div><button onClick={runClean} disabled={busy} className="button-primary mt-7" data-testid="button-clean-data">{busy ? 'Normalizing…' : 'Clean and normalize'} <ArrowRight className="h-4 w-4" /></button></>}{stage === 'resolve' && cleaned && !resolved && <><div className="mt-7 rounded-lg border border-primary/20 bg-primary/5 p-5"><div className="flex items-start gap-3"><CheckCircle2 className="mt-0.5 h-5 w-5 text-primary" /><div><div className="font-semibold">Records normalized</div><div className="mt-1 text-sm text-muted-foreground">{cleaned.rows.length} rows are ready for entity resolution.</div></div></div></div><button onClick={runResolve} disabled={busy} className="button-primary mt-7" data-testid="button-resolve-entities">{busy ? 'Resolving…' : 'Resolve company entities'} <ArrowRight className="h-4 w-4" /></button></>}{stage === 'resolve' && resolved && <><div className="mt-7 grid grid-cols-3 gap-3">{[['Resolved', resolved.resolvedCount], ['Review', resolved.reviewCount], ['Unresolved', resolved.unresolvedCount]].map(([label, value]) => <div className="rounded-lg bg-secondary/65 p-4" key={String(label)}><div className="eyebrow text-muted-foreground">{label}</div><div className="data-mono mt-2 text-xl font-bold">{value}</div></div>)}</div><p className="mt-5 text-sm leading-6 text-muted-foreground">Entity resolution proposes matches. Review uncertain matches in the entity queue before importing.</p><button onClick={runImport} disabled={busy} className="button-primary mt-7" data-testid="button-import-data">{busy ? 'Importing…' : 'Import reviewed dataset'} <Download className="h-4 w-4" /></button></>}</div>}{stage === 'imported' && result && <div className="flex min-h-[400px] flex-col items-center justify-center text-center"><div className="mb-5 rounded-full bg-primary/10 p-4 text-primary"><Check className="h-8 w-8" /></div><h2 className="text-2xl font-semibold">Dataset imported</h2><p className="mt-2 text-sm text-muted-foreground">{result.importedRows} of {result.processedRows} rows are now available for review.</p><div className="mt-7 flex gap-3"><Link href="/data/datasets" className="button-primary" data-testid="link-view-datasets">View dataset history <ArrowRight className="h-4 w-4" /></Link><button onClick={() => { setStage('upload'); setResult(null); setPreview(null); }} className="button-secondary" data-testid="button-import-another">Import another</button></div></div>}</section><aside className="space-y-6"><section className="panel p-6"><div className="eyebrow text-muted-foreground">Intake principles</div><h2 className="mt-2 text-lg font-semibold">Trace every change</h2><div className="mt-5 space-y-4 text-sm leading-6 text-muted-foreground">{[['01', 'Preview first', 'No rows are written during upload.'], ['02', 'Validate openly', 'Issues and quality are visible before cleaning.'], ['03', 'Resolve carefully', 'Uncertain company matches go to a human queue.']].map(([num, title, text]) => <div className="flex gap-3" key={num}><span className="data-mono text-primary">{num}</span><div><div className="font-semibold text-foreground">{title}</div><div>{text}</div></div></div>)}</div></section><Disclaimer network /></aside></div></PageFrame>;
}

function Datasets() {
  const query = useGetDatasets(); const [selected, setSelected] = useState<number | null>(null); const detail = useGetDataset(selected ?? 0, { query: { enabled: selected !== null, queryKey: ['/api/data/datasets', selected ?? 0] } });
  return <PageFrame><PageHeader eyebrow="Data room / provenance" title="Dataset history" description="A durable record of every import, its quality profile, and what entered the review workspace." action={<Link href="/data" className="button-primary" data-testid="link-add-dataset"><Plus className="h-4 w-4" /> Add dataset</Link>} /><QueryState loading={query.isLoading} error={query.error} onRetry={() => query.refetch()}>{query.data?.length ? <div className="grid gap-4">{query.data.map((dataset) => <button onClick={() => setSelected(dataset.id)} className="panel panel-hover grid items-center gap-4 p-5 text-left md:grid-cols-[1.5fr_.7fr_.7fr_.7fr_auto]" key={dataset.id} data-testid={`button-dataset-${dataset.id}`}><div className="flex items-center gap-3"><div className="rounded-lg bg-primary/10 p-2.5 text-primary"><FileSpreadsheet className="h-5 w-5" /></div><div><div className="font-semibold">{dataset.filename}</div><div className="mt-1 text-xs text-muted-foreground">{dataset.source} · uploaded {fmtDate(dataset.uploadedAt)}</div></div></div><div><div className="eyebrow text-muted-foreground">Rows</div><div className="data-mono mt-1 text-sm">{dataset.totalRows.toLocaleString()}</div></div><div><div className="eyebrow text-muted-foreground">Quality</div><div className="data-mono mt-1 text-sm">{dataset.qualityScore.toFixed(1)}%</div></div><div><div className="eyebrow text-muted-foreground">Coverage</div><div className="mt-1 text-xs text-muted-foreground">{dataset.companies} companies · {dataset.tenders} tenders</div></div><StatusPill level={dataset.status === 'Failed' ? 'Elevated' : dataset.status === 'Imported' ? 'Low' : 'Moderate'}>{dataset.status}</StatusPill></button>)}</div> : <Empty title="No datasets imported" text="Upload a procurement CSV to create your first provenance record." />}</QueryState>{selected !== null && <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/25 p-5" onClick={() => setSelected(null)}><div className="panel max-h-[80vh] w-full max-w-lg overflow-auto p-6" onClick={(e) => e.stopPropagation()}><div className="flex items-start justify-between"><div><div className="eyebrow text-primary">Dataset detail</div><h2 className="mt-2 text-xl font-semibold">{detail.data?.filename ?? 'Loading record'}</h2></div><button onClick={() => setSelected(null)} className="icon-button" data-testid="button-close-dataset"><X className="h-4 w-4" /></button></div>{detail.isLoading ? <div className="mt-6"><LoadingPanel /></div> : detail.data && <div className="mt-6 space-y-3 text-sm">{[['Status', detail.data.status], ['Valid rows', detail.data.validRows], ['Warnings', detail.data.warningRows], ['Errors', detail.data.errorRows], ['Uploaded', fmtDate(detail.data.uploadedAt)]].map(([label, value]) => <div className="flex justify-between border-b hairline py-3" key={String(label)}><span className="text-muted-foreground">{label}</span><span className="data-mono font-semibold">{value}</span></div>)}</div>}</div></div>}</PageFrame>;
}

function Entities() {
  const query = useGetEntityReview(); const confirm = useConfirmEntity(); const reject = useRejectEntity(); const create = useCreateEntity(); const [active, setActive] = useState<number | null>(null); const [canonical, setCanonical] = useState('');
  const update = (id: number, action: 'confirm' | 'reject') => { const mutation = action === 'confirm' ? confirm : reject; mutation.mutate({ id }, { onSuccess: () => query.refetch() }); };
  return <PageFrame><PageHeader eyebrow="Data room / entity resolution" title="Entity review" description="Confirm or reject uncertain matches before they influence participation analysis. Each decision is recorded against the source name." /><div className="mb-6 grid gap-4 sm:grid-cols-3"><Metric label="Review queue" value={query.data?.length ?? '—'} detail="Awaiting analyst decision" icon={GitBranch} accent /><Metric label="Decision rule" value="Human" detail="No uncertain match auto-imports" icon={Users} /><Metric label="Traceability" value="On" detail="Source names retained" icon={FileCheck2} /></div><QueryState loading={query.isLoading} error={query.error} onRetry={() => query.refetch()}>{query.data?.length ? <div className="space-y-3">{query.data.map((match) => <div className="panel p-5" key={match.id} data-testid={`row-entity-${match.id}`}><div className="flex flex-col justify-between gap-4 md:flex-row md:items-center"><div className="flex items-start gap-4"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-secondary font-bold text-primary">{match.sourceName.slice(0, 2).toUpperCase()}</div><div><div className="eyebrow text-muted-foreground">{match.source} · {match.status}</div><div className="mt-1 text-lg font-semibold">{match.sourceName}</div><div className="mt-1 text-sm text-muted-foreground">Suggested match: <span className="font-medium text-foreground">{match.suggestedCompany ?? 'No candidate'}</span></div></div></div><div className="flex items-center gap-2"><span className="data-mono mr-2 text-sm text-primary">{match.confidence.toFixed(0)}% confidence</span><button disabled={confirm.isPending || reject.isPending} onClick={() => update(match.id, 'reject')} className="button-secondary" data-testid={`button-reject-entity-${match.id}`}><XCircle className="h-4 w-4" /> Reject</button><button disabled={confirm.isPending || reject.isPending} onClick={() => update(match.id, 'confirm')} className="button-primary" data-testid={`button-confirm-entity-${match.id}`}><CheckCircle2 className="h-4 w-4" /> Confirm</button></div></div><div className="mt-5 grid gap-3 border-t hairline pt-4 text-xs text-muted-foreground sm:grid-cols-3"><span>Name similarity <b className="data-mono text-foreground">{match.nameSimilarity.toFixed(0)}%</b></span><span>Address similarity <b className="data-mono text-foreground">{match.addressSimilarity?.toFixed(0) ?? '—'}%</b></span><button className="text-left font-semibold text-primary hover:underline md:text-right" onClick={() => setActive(active === match.id ? null : match.id)} data-testid={`button-create-entity-${match.id}`}>{active === match.id ? 'Close create form' : 'Not the right entity?'}</button></div>{active === match.id && <div className="mt-4 flex flex-col gap-2 rounded-lg bg-secondary/55 p-4 sm:flex-row"><input value={canonical} onChange={(e) => setCanonical(e.target.value)} placeholder="Canonical company name" className="input flex-1" data-testid={`input-canonical-${match.id}`} /><button onClick={() => create.mutate({ data: { sourceName: match.sourceName, canonicalName: canonical } }, { onSuccess: () => { setActive(null); setCanonical(''); query.refetch(); } })} disabled={!canonical.trim() || create.isPending} className="button-primary" data-testid={`button-save-canonical-${match.id}`}><Plus className="h-4 w-4" /> Create entity</button></div>}</div>)}</div> : <Empty title="Entity queue is clear" text="No uncertain company matches need a decision right now." />}</QueryState><Disclaimer network /></PageFrame>;
}

function SettingsPage() {
  const [saved, setSaved] = useState(false); return <PageFrame><PageHeader eyebrow="Workspace / preferences" title="Settings" description="A quiet place for workspace preferences. Core analysis configuration stays explicit and reviewable." /><div className="grid gap-6 xl:grid-cols-[1fr_320px]"><section className="panel p-6"><div className="eyebrow text-muted-foreground">Workspace identity</div><h2 className="mt-2 text-lg font-semibold">Analyst room</h2><div className="mt-6 space-y-5"><label className="block text-sm font-medium">Workspace name<input defaultValue="National procurement evidence room" className="input mt-2" data-testid="input-workspace-name" /></label><label className="block text-sm font-medium">Default review language<select defaultValue="English" className="input mt-2" data-testid="select-language"><option>English</option><option>Hindi</option></select></label><label className="flex items-center gap-3 text-sm"><input type="checkbox" defaultChecked className="h-4 w-4 accent-primary" data-testid="checkbox-notifications" /> Notify me when new indicators enter the queue</label><button onClick={() => setSaved(true)} className="button-primary" data-testid="button-save-settings">{saved ? 'Preferences saved' : 'Save preferences'} <Check className="h-4 w-4" /></button></div></section><section className="panel p-6"><div className="eyebrow text-muted-foreground">About the workspace</div><h2 className="mt-2 text-lg font-semibold">BidShield</h2><p className="mt-4 text-sm leading-6 text-muted-foreground">Evidence-first procurement analytics for public-sector investigators. Indicators are prompts for careful review, never verdicts.</p><div className="mt-6 border-t hairline pt-5 text-xs text-muted-foreground"><div>Build <span className="float-right data-mono text-foreground">0.1.0</span></div><div className="mt-3">Screening engine <span className="float-right text-primary">Connected</span></div></div></section></div></PageFrame>;
}

function Router() {
  return <ErrorBoundary resetKey={window.location.pathname}><Shell><Switch><Route path="/" component={Dashboard} /><Route path="/dashboard" component={Dashboard} /><Route path="/tenders" component={Tenders} /><Route path="/tenders/:id" component={TenderDetailPage} /><Route path="/companies" component={Companies} /><Route path="/companies/:id" component={CompanyDetailPage} /><Route path="/investigations" component={Investigations} /><Route path="/investigations/:id" component={InvestigationDetailPage} /><Route path="/network" component={NetworkPage} /><Route path="/data" component={DataPage} /><Route path="/data/datasets" component={Datasets} /><Route path="/data/entities" component={Entities} /><Route path="/settings" component={SettingsPage} /><Route component={NotFound} /></Switch></Shell></ErrorBoundary>;
}
function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}
export default App;